@import url("https://fontsapi.zeoseven.com/2/main/result.css");

body {
    font-family: "LXGW ZhenKai GB";
    font-weight: normal;
}
/* 限制只在聊天消息区域内的头像显示头像框 */
#chat .mes .avatar {
    position: relative;
    width: 140px;/* 头像宽度 */
    height: 140px;/* 头像高度 */
    border-radius: 50%;
    overflow: visible; /* 改为visible允许内容溢出 */
    flex-shrink: 0;
    z-index: 1;
}

#chat .mes .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 0% 0% 0 0; /* 只圆上面两个角 */
    position: relative;
    z-index: 1;
}

/* 添加头像框效果 - 只在聊天消息区域显示 */
#chat .mes .avatar::after {
    content: '';
    position: absolute;
    top: 33%;/* 头像框位置，数字越大越往下 */
    left: 58%;/* 头像框位置，数字越大越往右 */
    transform: translate(-50%, -50%);
    width: 430px; /* 头像框尺寸，要比头像大 */
    height: 430px; /* 头像框尺寸，要比头像大 */
    background-image: url('https://s3.bmp.ovh/2026/03/01/927MedlU.png'); /* 替换为您的头像框图片URL */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2; /* 确保头像框在头像之上 */
    pointer-events: none;
}




/* 合并后的 .mes 规则 */
.mes {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important; 
    gap: 5px;
    position: relative;
    z-index: 0;
}
.mes .text-content {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    /* position: relative;   移除或注释掉 */
    /* z-index: 100;         移除或注释掉 */
}
/* 三个元素的基础样式 */
.mes .mesIDDisplay,
.mes .timestamp,
.mes .name_text {
    position: relative;  /* 如果不用绝对定位，保持 relative 即可 */
    z-index: 1000 !important;
}


/* 单独调整每个元素的对齐方式 */
.mes .name_text {
    text-align: left;
    flex: 0 0 auto;      /* 不拉伸 */
}

.mes .timestamp {
    text-align: right;
    flex: 0 0 auto;
}
.mes .mesIDDisplay {
    text-align: right;
    flex: 1 1 auto;      /* 允许拉伸占满剩余空间 */
    order: -1;            /* 默认顺序，如果想放最左边可设为 -1 */
}

/* 如果想让 ID 在名字左边，把 order 设为 -1 */
.mes .mesIDDisplay {
    order: -1;
}




/* 确保头像框在文字之下 */
#chat .mes .avatar::after {
    /* 保留您原有的头像框样式 */
    z-index: 2; /* 这个值小于1000，所以会被文字覆盖 */
    /* 其他样式不变 */
}


/* 导航栏背景 */
/* 终极自由控制方案 - 替换 #top-bar::before */
#top-bar::before {
    content: '';
    position: absolute; /* 基础定位 */
    background-image: url('https://s3.bmp.ovh/2026/02/28/CqYEd8nf.png');
    background-repeat: no-repeat;
    z-index: -1;
    pointer-events: none;

    /* ========== 【核心控制区】请调整以下属性 ========== */

    /* 1. 控制背景“画布”本身在导航栏内的位置（移动整个画布） */
    top: 110%;   /* 垂直起点：改为 0px 即贴顶，50%即居中，100%即贴底 */
    left: 50%;  /* 水平起点：改为 0px 即贴左，50%即居中，100%即贴右 */

    /* 2. 控制背景图片在“画布”内的对齐方式（画布内部调整） */
    background-position: center center; /* 图片在画布内居中。可改为 left top, right bottom 等 */

    /* 3. 控制背景“画布”的尺寸（您想显示多大范围的图片） */
    width: 100%;  /* 画布宽度：占导航栏的比例。可设为 300px, 50% 等 */
    height: 230%; /* 画布高度：可大于100%以实现“溢出”效果。可设为 100px, 150% 等 */

    /* 4. 控制背景图片的缩放方式（如何适配画布）*/
    background-size: 100% 100%; /* 填满画布，可能变形。推荐改用下方选项 */
    /* background-size: contain; */ /* 在画布内完整显示图片，可能留白 */
    /* background-size: cover; */   /* 覆盖画布，可能裁剪 */
    /* background-size: 200px auto; */ /* 固定宽度200px，高度自适应 */

    /* 5. (高级) 使用 transform 进行像素级微调（移动整个画布） */
    transform: translate(-50%, -50%); /* 与 top:50%; left:50%; 组合实现完美居中 */
    /* 如果想右移20px，下移10px：transform: translate(calc(-50% + 20px), calc(-50% + 10px)); */
}


